def multiplicative_breakdown(start, stop):
    if isinstance(start, bool) or isinstance(stop, bool) or not isinstance(start, int) or not isinstance(stop, int):
        raise ValueError("bounds must be integers")
    if start < 2 or stop < start:
        raise ValueError("invalid bounds")
    result = {}
    for value in range(start, stop + 1):
        remaining = value
        factor = 2
        factors = []
        while factor * factor <= remaining:
            if remaining % factor == 0:
                factors.append(factor)
                remaining //= factor
            factor += 1
        if remaining > 1:
            factors.append(remaining)
        result[value] = tuple(factors)
    return result


def render_breakdowns(catalog):
    if not isinstance(catalog, dict):
        raise ValueError("catalog must be a dictionary")
    lines = []
    for number, factors in catalog.items():
        if isinstance(number, bool) or not isinstance(number, int) or number < 2:
            raise ValueError("invalid catalog key")
        if not isinstance(factors, tuple) or not factors or any(isinstance(f, bool) or not isinstance(f, int) for f in factors):
            raise ValueError("invalid factor tuple")
        product = 1
        for factor in factors:
            product *= factor
        if product != number:
            raise ValueError("factors do not match key")
        lines.append(f"{number}: " + " * ".join(str(factor) for factor in factors))
    return "\n".join(lines)

