import unittest

from solution import multiplicative_breakdown, render_breakdowns


class BreakdownTests(unittest.TestCase):
    def test_breakdown_range_order_and_repeated_factors(self):
        result = multiplicative_breakdown(2, 12)
        self.assertEqual(list(result), list(range(2, 13)))
        self.assertEqual(result[2], (2,))
        self.assertEqual(result[8], (2, 2, 2))
        self.assertEqual(result[10], (2, 5))
        self.assertEqual(result[12], (2, 2, 3))

    def test_single_prime_boundary(self):
        self.assertEqual(multiplicative_breakdown(13, 13), {13: (13,)})

    def test_invalid_ranges(self):
        for args in [(True, 3), (2, False), (2.0, 3), (2, 3.0), (1, 2), (4, 3)]:
            with self.subTest(args=args), self.assertRaises(ValueError):
                multiplicative_breakdown(*args)

    def test_render_preserves_iteration_order_and_input(self):
        catalog = {6: (2, 3), 4: (2, 2), 7: (7,)}
        before = dict(catalog)
        self.assertEqual(render_breakdowns(catalog), "6: 2 * 3\n4: 2 * 2\n7: 7")
        self.assertEqual(catalog, before)
        self.assertEqual(render_breakdowns({}), "")

    def test_render_rejects_malformed_entries(self):
        invalid = [
            {1: (1,)},
            {4: []},
            {4: ()},
            {4: (2, "2")},
            {6: (2, 2)},
            {"4": (2, 2)},
        ]
        for catalog in invalid:
            with self.subTest(catalog=catalog), self.assertRaises(ValueError):
                render_breakdowns(catalog)


if __name__ == "__main__":
    unittest.main()

